	/**
	 * Default Constructor
	 */
    public SellerService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new SellerEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(SellerRepository.class) );
		this.validator		= applicationContext.getBean(SellerValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Seller
	 */
		public Seller createSeller( CreateSellerCommand command ) {

		Seller entity = new Seller();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setSellerId( command.getSellerId() );
            entity.setName( command.getName() );
            entity.setSellerCode( command.getSellerCode() );
            entity.setContactEmail( command.getContactEmail() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Seller {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateSellerCommand
	 * @return		Seller
	 */
	public Seller updateSeller( UpdateSellerCommand command ) {

		Seller entity = new Seller();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setSellerId( command.getSellerId() );
            entity.setName( command.getName() );
            entity.setSellerCode( command.getSellerCode() );
            entity.setContactEmail( command.getContactEmail() );
            entity.setMerchant( command.getMerchant() );
            entity.setProducts( command.getProducts() );
            entity.setPayouts( command.getPayouts() );
            entity.setOrders( command.getOrders() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Seller {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteSellerCommand
	 */
	public void delete( DeleteSellerCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getSellerId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Seller {0} ", id );

	}

	/**
	 * Method to retrieve the Seller via SellerFetchOneSummary
	 * @param 	summary SellerFetchOneSummary
	 * @return 	SellerFetchOneResponse
	 */
	public Seller getSeller( SellerFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "SellerFetchOneSummary arg cannot be null" );

		Seller entity = null;
		UUID id = summary.getSellerId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Seller using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Sellers
	 *
	 * @return 	List<Seller>
	 */
    public List<Seller> getAllSeller() {
		List<Seller> list = projector.findAll( new FindAllSellerQuery() );
		return list;
	}

	/**
	 * assign Merchant on Seller
	 * @param		command AssignMerchantToSellerCommand
	 */
	public void assignMerchant( AssignMerchantToSellerCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignMerchant(command.getSellerId(), command.getAssignment());

	}

	/**
	 * unAssign Merchant on Seller
	 * @param		command UnAssignMerchantFromSellerCommand
	 */
	public void unAssignMerchant( UnAssignMerchantFromSellerCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignMerchant(command.getSellerId());
	}
	

